namespace ghidra.feature.vt.gui.actions;






using docking;
using docking.action;
using docking.tool;
using generic.theme;
using ghidra.feature.vt.api.db;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.util;

public class UndoAction : DockingAction {
	private VTController controller;

	public UndoAction(VTController controller) : base("Undo", VTPlugin.OWNER)
    {
		this.controller = controller;
		setHelpLocation(new HelpLocation(ToolConstants.TOOL_HELP_TOPIC, "Undo"));
		string[] menuPath = new string[] { ToolConstants.MENU_EDIT, "&Undo" };
		string group = "ZZUndo";
		Icon icon = new GIcon("icon.undo");
		MenuData menuData = new MenuData(menuPath, icon, group);
		menuData.setMenuSubGroup("1Undo"); // make this appear above the redo menu item
		setMenuBarData(menuData);
		setToolBarData(new ToolBarData(icon, group));
		setDescription("Undo");
		setKeyBindingData(new KeyBindingData('Z', InputEvent.CTRL_MASK));
	}

	/* @Override */
	public void actionPerformed(ActionContext programContext) {
		VTSessionDB session = (VTSessionDB) controller.getSession();
		if (session == null) {
			return;
		}
		try {
			session.undo();
		}
		catch (IOException e) {
			Msg.showError(this, null, null, null, e);
		}
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		VTSessionDB session = (VTSessionDB) controller.getSession();
		if (session != null) {
			if (session.canUndo()) {
				string name = session.getName();
				getMenuBarData().setMenuItemName("Undo " + name);
				string tip = HTMLUtilities.toWrappedHTML("Undo " + session.getUndoName());
				setDescription(tip);
				return true;
			}
		}
		setDescription("Undo");
		getMenuBarData().setMenuItemName("Undo");
		return false;
	}

}
